# Monthly reporting service

`app/report.py` calculates monthly report contributions from validated source rows. Investigate the customer request in `issue.json`. Amounts are integer USD cents.

Run the baseline tests with `python3 -m unittest discover -s tests -v`. These cover existing behavior and may not establish every business requirement.
"""Current reporting implementation. Inputs have already passed schema validation."""


def contributions(rows, month, config):
    result = []
    for row in rows:
        included = (row[config["date_basis"]][:7] == month
                    and row["kind"] in config["included_kinds"])
        amount = row["amount_cents"]
        contribution = -amount if row["kind"] == "RETURN" else amount
        result.append({"row_id": row["id"], "included": included,
                       "contribution_cents": contribution if included else 0})
    return result


def total(rows, month, config):
    return sum(row["contribution_cents"] for row in contributions(rows, month, config))
import unittest
from app.report import contributions, total

CONFIG = {"date_basis": "posted_on", "included_kinds": ["SALE", "RETURN"]}

def row(kind="SALE", amount=10000, posted="2026-09-15"):
    return {"id": "X-1", "kind": kind, "amount_cents": amount, "feed": "ATLAS",
            "schema_version": "2", "invoice_on": "2026-09-15", "posted_on": posted}

class ExistingBehavior(unittest.TestCase):
    def test_sale(self):
        self.assertEqual(total([row()], "2026-09", CONFIG), 10000)
    def test_positive_return(self):
        self.assertEqual(total([row("RETURN", 2500)], "2026-09", CONFIG), -2500)
    def test_excluded_transfer(self):
        self.assertEqual(total([row("TRANSFER")], "2026-09", CONFIG), 0)
    def test_posted_month(self):
        self.assertEqual(total([row(posted="2026-10-01")], "2026-09", CONFIG), 0)
    def test_integer_cents(self):
        self.assertEqual(total([row(amount=10001), row("RETURN", 2)], "2026-09", CONFIG), 9999)

if __name__ == "__main__":
    unittest.main()

